{"code": "fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"
pos = simulate_move(fen)
moves = sorted(pos["legal_moves"])

def score(f):
    p = simulate_move(f)
    if p["game_over"]:
        w = p.get("winner")
        if w == "w": return 100000
        if w == "b": return -100000
        return 0
    # piece values
    val = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0,'p':-100,'n':-320,'b':-330,'r':-500,'q':-900,'k':0}
    tot = 0
    rows = f.split()[0].split('/')
    central = {'d4','e4','d5','e5'}
    for ri,row in enumerate(rows):
        rank = 8-ri
        col = 0
        for ch in row:
            if ch.isdigit():
                col += int(ch)
            else:
                sq = chr(ord('a')+col)+str(rank)
                tot += val[ch]
                if sq in central:
                    if ch.isupper(): tot += 12
                    else: tot -= 12
                col += 1
    # check
    if p["in_check"]:
        if p["turn"]=='b': tot += 25
        else: tot -= 25
    return tot

best=None; bestscore=None
for m in moves:
    af = simulate_move(fen, m)
    black_moves = sorted(af["legal_moves"])
    if af["game_over"]:
        cand = score(af["fen"])
    else:
        scores=[]
        for bm in black_moves:
            bf = simulate_move(af["fen"], bm)
            scores.append(score(bf["fen"]))
        cand = min(scores)
    if bestscore is None or cand>bestscore:
        bestscore=cand; best=m
    print(m, cand)
print("BEST", best, bestscore)
play_move(best)"}

